import { names } from '../data';

function Table({ range }) {
    // Calculating the time difference of two dates
    const difference_in_time = range[0].endDate - range[0].startDate;
    // Calculating the no. of days between two dates
    const difference_in_days = Math.round(difference_in_time / (1000 * 3600 * 24));

    const startDate = range[0].startDate;
    const endDate = range[0].endDate;
    const options = { month: 'short', day: 'numeric' };
    const startMonthAndDate = startDate.toLocaleDateString('en-US', options);
    const endMonthAndDate = endDate.toLocaleDateString('en-US', options);

    return (
        <table id='table'>
            <thead>
                <tr>
                    <th>Date</th>
                    {names.map((name, key) =>
                        <th id={key}>
                            {name}
                        </th>
                    )}
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>{startMonthAndDate}</td>
                    {names.map((name, key) =>

                        <td>
                            <label>Open - 4:00 pm</label>
                            <input type="number" defaultValue="0" />
                            <label>4:00 pm - Close</label>
                            <input type="number" defaultValue="0" />
                        </td>
                    )}
                </tr>
                <tr>
                    <td>2</td>
                    <td>Jacob</td>
                    <td>Thornton</td>
                    <td>@fat</td>
                </tr>
                <tr>
                    <td>3</td>
                    <td colSpan={2}>Larry the Bird</td>
                    <td>@twitter</td>
                </tr>
            </tbody>
            <thead>
                <tr>
                    <th>Name</th>
                </tr>
                <tr>
                    {names.map((name, key) =>
                        <th id={key}>
                            {name}
                        </th>)
                    }
                </tr>
            </thead>
            <tbody>
                {names.map((key) =>
                    <td id={key}>
                        <input type="number" defaultValue="0" />
                        <input type="number" defaultValue="0" />
                    </td>
                )}
            </tbody>
        </table>
    );
}

export default Table;
